def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    anchors = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]
    if len(anchors) < 2:
        return out

    def nearby_count(anchor):
        r, c = anchor
        return sum(
            1 for y in range(max(0, r - 3), min(h, r + 4))
            for x in range(max(0, c - 3), min(w, c + 4))
            if grid[y][x] not in (0, 5)
        )

    source = max(anchors, key=nearby_count)
    target = next(a for a in anchors if a != source)
    sr, sc = source
    tr, tc = target
    out[tr][tc] = 0
    for r in range(h):
        for c in range(w):
            value = grid[r][c]
            if value not in (0, 5):
                nr, nc = tr + r - sr, tc + c - sc
                if 0 <= nr < h and 0 <= nc < w:
                    out[nr][nc] = value
    return out
